  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "
    {
      users(first: 20, where: {name: {contains: \"Maya Chen\"}}) {
        nodes {
          id
          name
          email
        }
      }
    }"
  }'
